PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE IF NOT EXISTS "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE IF NOT EXISTS "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE TABLE IF NOT EXISTS "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE TABLE IF NOT EXISTS "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE IF NOT EXISTS "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" varchar not null, "queue" varchar not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "personal_access_tokens" ("id" integer primary key autoincrement not null, "tokenable_type" varchar not null, "tokenable_id" integer not null, "name" text not null, "token" varchar not null, "abilities" text, "last_used_at" datetime, "expires_at" datetime, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "roles" ("id" integer primary key autoincrement not null, "name" varchar not null, "slug" varchar not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar, "password" varchar not null, "created_at" datetime, "updated_at" datetime, "username" varchar not null, "mobile" varchar, "role_id" integer not null, "is_active" tinyint(1) not null default '1', foreign key("role_id") references "roles"("id"));
CREATE TABLE IF NOT EXISTS "permissions" ("id" integer primary key autoincrement not null, "name" varchar not null, "slug" varchar not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "role_permissions" ("role_id" integer not null, "permission_id" integer not null, foreign key("role_id") references "roles"("id") on delete cascade, foreign key("permission_id") references "permissions"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "menu_categories" ("id" integer primary key autoincrement not null, "name" varchar not null, "description" text, "image" varchar, "sort_order" integer not null default '0', "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "menu_items" ("id" integer primary key autoincrement not null, "name" varchar not null, "description" text, "category_id" integer not null, "dietary_type" varchar, "price" numeric not null, "is_available" tinyint(1) not null default '1', "is_chef_special" tinyint(1) not null default '0', "sort_order" integer not null default '0', "spicy_level" integer, "created_at" datetime, "updated_at" datetime, foreign key("category_id") references "menu_categories"("id") on delete restrict);
CREATE TABLE IF NOT EXISTS "tables" ("id" integer primary key autoincrement not null, "number" varchar not null, "description" varchar, "capacity" integer not null, "code" varchar not null, "sort_order" integer not null default '0', "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE INDEX "sessions_user_id_index" on "sessions" ("user_id");
CREATE INDEX "sessions_last_activity_index" on "sessions" ("last_activity");
CREATE INDEX "cache_expiration_index" on "cache" ("expiration");
CREATE INDEX "cache_locks_expiration_index" on "cache_locks" ("expiration");
CREATE INDEX "jobs_queue_index" on "jobs" ("queue");
CREATE INDEX "failed_jobs_connection_queue_failed_at_index" on "failed_jobs" ("connection", "queue", "failed_at");
CREATE UNIQUE INDEX "failed_jobs_uuid_unique" on "failed_jobs" ("uuid");
CREATE INDEX "personal_access_tokens_tokenable_type_tokenable_id_index" on "personal_access_tokens" ("tokenable_type", "tokenable_id");
CREATE UNIQUE INDEX "personal_access_tokens_token_unique" on "personal_access_tokens" ("token");
CREATE INDEX "personal_access_tokens_expires_at_index" on "personal_access_tokens" ("expires_at");
CREATE UNIQUE INDEX "roles_slug_unique" on "roles" ("slug");
CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE UNIQUE INDEX "users_username_unique" on "users" ("username");
CREATE UNIQUE INDEX "users_mobile_unique" on "users" ("mobile");
CREATE UNIQUE INDEX "permissions_slug_unique" on "permissions" ("slug");
CREATE UNIQUE INDEX "role_permissions_role_id_permission_id_unique" on "role_permissions" ("role_id", "permission_id");
CREATE INDEX "menu_categories_is_active_sort_order_index" on "menu_categories" ("is_active", "sort_order");
CREATE INDEX "menu_categories_sort_order_index" on "menu_categories" ("sort_order");
CREATE INDEX "menu_items_category_id_index" on "menu_items" ("category_id");
CREATE INDEX "menu_items_dietary_type_index" on "menu_items" ("dietary_type");
CREATE INDEX "menu_items_is_available_index" on "menu_items" ("is_available");
CREATE INDEX "menu_items_is_chef_special_index" on "menu_items" ("is_chef_special");
CREATE INDEX "menu_items_sort_order_index" on "menu_items" ("sort_order");
CREATE UNIQUE INDEX "tables_number_unique" on "tables" ("number");
CREATE UNIQUE INDEX "tables_code_unique" on "tables" ("code");
CREATE INDEX "tables_is_active_sort_order_index" on "tables" ("is_active", "sort_order");
CREATE INDEX "tables_sort_order_index" on "tables" ("sort_order");
COMMIT;
